#plot the correlation between size of individuals from different stage groups with size of stage groups
#############################################################################
#load the indiviudal size data
SizeData=read_xlsx("Data/MQ test_ Count and Size data.xlsx", sheet = "SizeData")
# get the data for control
SizeData_C_raw<-subset(SizeData,treatment=="C")

#-------------------------------------------------------------------------------
#Standardize the body size within each stage group to [0,1]
# List of stage columns to be standardized
stage_size_columns <- c(
  "F", "FM", "SM", 
  "tritos", "protos", "larvae", "eggs", 
  "Qtritos", "Qprotos", "Qlarvae", 
  "deutos", "Qdeutos"
)

# Copy data to preserve original
SizeData_C <- SizeData_C_raw

# Track total number of outliers
outlier_counts <- numeric(length(stage_size_columns))
names(outlier_counts) <- stage_size_columns

# Step 1: Remove outliers per stage column
for (col in stage_size_columns) {
  vals <- SizeData_C[[col]]
  q1 <- quantile(vals, 0.25, na.rm = TRUE)
  q3 <- quantile(vals, 0.75, na.rm = TRUE)
  iqr <- q3 - q1
  lower <- q1 - 3 * iqr
  upper <- q3 + 3 * iqr
  
  # Identify outliers
  outliers <- which(vals < lower | vals > upper)
  outlier_counts[col] <- length(outliers)
  
  # Replace with NA
  SizeData_C[[col]][outliers] <- NA
}


# Apply min-max scaling (0–1) to each stage column
SizeData_C_scaled <- SizeData_C %>%
  mutate(across(
    all_of(stage_size_columns),
    ~ (. - min(., na.rm = TRUE)) / (max(., na.rm = TRUE) - min(., na.rm = TRUE)),
    .names = "{.col}"
  ))

#-------------------------------------------------------------------------------
#merge countdata and size data
merged_data<- left_join(SizeData_C, CountData_C_extd, by = c("day", "tube"))
merged_data_scaled <- left_join(SizeData_C_scaled, CountData_C_extd, by = c("day", "tube"))

#-------------------------------------------------------------------------------
#analyze the size vs abundance coefficient
# List of relevant stages and their corresponding abundance columns
stages <- c("F", "FM", "SM","Qtritos", "Qprotos", "Qdeutos", "Qlarvae",
            "tritos", "deutos", "protos","larvae","eggs")
abundance_cols <- c("noeggs", "nojuveniles","noadults","nototal", "q")


library("corrplot")
library(psych)

#select the columns of interest for correlation analysis

cor_df <- merged_data_scaled %>%
  select(all_of(c(stages, abundance_cols))) 

# 1) Remove all-NA columns first
cor_df2 <- cor_df %>%
  select(where(~ !all(is.na(.)))) %>%
  select(where(~ sd(., na.rm = TRUE) > 0))

# 2) Correlation matrix
cor_res <- rcorr(as.matrix(cor_df2), type = "spearman")

R <- cor_res$r
P <- cor_res$P

# 3) BH-adjust only the upper triangle p-values
P_adj <- matrix(NA_real_, nrow = nrow(P), ncol = ncol(P),
                dimnames = dimnames(P))

upper_idx <- upper.tri(P, diag = FALSE)
P_adj[upper_idx] <- p.adjust(P[upper_idx], method = "BH")

# mirror to lower triangle
P_adj[lower.tri(P_adj)] <- t(P_adj)[lower.tri(P_adj)]
diag(P_adj) <- 0

#plot the correlation coefficient
tiff("Results/Correlation between Abundance and individual size.tiff", 
     width = 5, height = 5, units = "in", res = 600)

corrplot(
  R,
  method = "circle",
  type = "upper",
  order = "original",
  tl.col = "black",
  tl.srt = 45,
  p.mat = P_adj,
  sig.level = c(0.001,0.01,0.05), #only plot the one that are statistically significant
  insig = "label_sig",
  pch.cex = 0.8,
  #insig = "blank"
)
dev.off()
