#stage specific body size vs relative density (q)
library(dplyr)
library(tidyr)
library(purrr)
library(mgcv)
library(ggplot2)
library(e1071)
library(patchwork)

################################################################################
# 1) Reshape to long format and calculate stage-level summaries
################################################################################

stage_summary <- merged_data_scaled %>%
  select(tube, day, q, all_of(stage_size_columns)) %>%
  pivot_longer(
    cols = all_of(stage_size_columns),
    names_to = "stage",
    values_to = "size"
  ) %>%
  filter(!is.na(size), !is.na(q)) %>%
  group_by(tube, day, q, stage) %>%
  summarise(
    mean_size = mean(size, na.rm = TRUE),
    cv_size   = ifelse(mean(size, na.rm = TRUE) == 0,
                       NA_real_,
                       sd(size, na.rm = TRUE) / mean(size, na.rm = TRUE)),
    skew_size = if (sum(!is.na(size)) >= 3) {
      e1071::skewness(size, type = 2, na.rm = TRUE)
    } else {
      NA_real_
    },
    n = sum(!is.na(size)),
    .groups = "drop"
  ) %>%
  mutate(
    tube  = factor(tube),
    stage = factor(stage, levels = stage_size_columns)
  )
################################################################################
# 2) Fit stage-specific GAMs for each metric
################################################################################

fit_stage_gam <- function(df, response) {
  fml <- as.formula(paste0(response, " ~ s(q, k = 5) + tube"))
  
  gam(
    formula = fml,
    data = df,
    method = "REML"
  )
}



# Split by stage
stage_split <- split(stage_summary, stage_summary$stage)

# Keep only stages with enough data
stage_split <- stage_split[
  sapply(stage_split, function(x) {
    nrow(x) >= 10 &&
      sum(!is.na(x$q)) >= 10 &&
      length(unique(x$q)) > 3
  })
]

# Fit one GAM per stage per metric
stage_gam_list <- lapply(stage_split, function(dat) {
  list(
    Mean = fit_stage_gam(dat, "mean_size"),
    CV   = fit_stage_gam(dat, "cv_size"),
    Skew = fit_stage_gam(dat, "skew_size")
  )
})

################################################################################
# 3) Prediction function
################################################################################

make_pred_df <- function(model, dat, response_name) {
  q_seq <- seq(
    min(dat$q, na.rm = TRUE),
    max(dat$q, na.rm = TRUE),
    length.out = 200
  )
  
  ref_tube <- levels(dat$tube)[1]
  
  newdat <- data.frame(
    q = q_seq,
    tube = factor(ref_tube, levels = levels(dat$tube))
  )
  
  pred <- predict(model, newdata = newdat, se.fit = TRUE)
  
  newdat$fit <- pred$fit
  newdat$lwr <- pred$fit - 1.96 * pred$se.fit
  newdat$upr <- pred$fit + 1.96 * pred$se.fit
  newdat$response <- response_name
  
  newdat
}

################################################################################
# 4) Build prediction data for all stages and metrics
################################################################################

pred_list <- imap_dfr(stage_gam_list, function(mods, st) {
  dat_st <- stage_summary %>% filter(stage == st)
  
  bind_rows(
    make_pred_df(mods$Mean, dat_st, "Mean") %>% mutate(stage = st),
    make_pred_df(mods$CV,   dat_st, "CV")   %>% mutate(stage = st),
    make_pred_df(mods$Skew, dat_st, "Skewness") %>% mutate(stage = st)
  )
})

pred_list <- pred_list %>%
  mutate(
    stage = factor(stage, levels = stage_size_columns),
    response = factor(response, levels = c("Mean", "CV", "Skewness"))
  )



################################################################################
# 5) extract the parameter from the gam model
################################################################################

library(dplyr)
library(purrr)
library(tibble)

extract_gam_summary <- function(model, stage_name, response_name) {
  sm <- summary(model)
  
  # Parametric terms
  ptab <- as.data.frame(sm$p.table)
  if (nrow(ptab) > 0) {
    ptab$term <- rownames(ptab)
    rownames(ptab) <- NULL
    ptab <- ptab %>%
      transmute(
        stage = stage_name,
        response = response_name,
        term_type = "parametric",
        term = term,
        estimate = Estimate,
        std_error = `Std. Error`,
        t_value = `t value`,
        F = NA_real_,
        edf = NA_real_,
        ref_df = NA_real_,
        p_value = `Pr(>|t|)`
      )
  } else {
    ptab <- tibble()
  }
  
  # Smooth terms
  stab <- as.data.frame(sm$s.table)
  if (nrow(stab) > 0) {
    stab$term <- rownames(stab)
    rownames(stab) <- NULL
    
    # Handle possible column-name differences safely
    stab$edf    <- if ("edf" %in% names(stab)) stab[["edf"]] else NA_real_
    stab$ref_df <- if ("Ref.df" %in% names(stab)) stab[["Ref.df"]] else NA_real_
    stab$F      <- if ("F" %in% names(stab)) stab[["F"]] else NA_real_
    stab$p_value <- if ("p-value" %in% names(stab)) stab[["p-value"]] else NA_real_
    
    stab <- stab %>%
      transmute(
        stage = stage_name,
        response = response_name,
        term_type = "smooth",
        term = term,
        estimate = NA_real_,
        std_error = NA_real_,
        t_value = NA_real_,
        F = F,
        edf = edf,
        ref_df = ref_df,
        p_value = p_value
      )
  } else {
    stab <- tibble()
  }
  
  bind_rows(ptab, stab) %>%
    mutate(
      adj_r2 = sm$r.sq,
      dev_explained = sm$dev.expl,
      n = sm$n
    )
}

appendix_gam_table <- imap_dfr(stage_gam_list, function(stage_models, stage_name) {
  imap_dfr(stage_models, function(model, response_name) {
    if (is.null(model)) return(NULL)
    extract_gam_summary(model, stage_name, response_name)
  })
})

appendix_gam_table

write.csv(
  appendix_gam_table,
  "Results/Appendix_GAM_model_table.csv",
  row.names = FALSE
)

