#extract p
stage_pvalues <- imap_dfr(stage_gam_list, function(stage_models, stage_name) {
  
  imap_dfr(stage_models, function(model, metric_name) {
    
    sm <- summary(model)
    
    tibble(
      stage = stage_name,
      metric = metric_name,
      p = sm$s.table[1, "p-value"],
      F = sm$s.table[1, "F"],
      edf = sm$s.table[1, "edf"],
      dev_explained = sm$dev.expl
    )
    
  })
  
})

stage_pvalues$metric[which(stage_pvalues$metric=="Skew")]<-"Skewness"

stage_pvalues <- stage_pvalues %>%
  mutate(
    stage = factor(stage, levels = rev(stages)),
    metric = factor(metric,
                    levels = c("Mean", "CV", "Skewness"))
  )


#convert to significance
stage_pvalues <- stage_pvalues %>%
  mutate(
    sig = case_when(
      p < 0.001 ~ "***",
      p < 0.01  ~ "**",
      p < 0.05  ~ "*",
      TRUE      ~ ""
    )
  )


get_stage_label_map <- function(metric_name) {
  stage_pvalues %>%
    filter(metric == metric_name) %>%
    mutate(stage_lab = paste0(as.character(stage), " ", sig)) %>%
    distinct(stage, stage_lab) %>%
    tibble::deframe()
}

plot_stage_metric <- function(metric_name, response_col, ylab) {
  
  stage_label_map <- get_stage_label_map(metric_name)
  
  plot_df <- stage_summary %>%
    filter(is.finite(.data[[response_col]]))
  
  pred_df <- pred_list %>%
    filter(response == metric_name)
  
  ggplot(plot_df, aes(x = q, y = .data[[response_col]])) +
    geom_point(aes(colour = tube),alpha = 0.25, size = 0.8) +
    geom_ribbon(
      data = pred_df,
      aes(x = q, ymin = lwr, ymax = upr),
      inherit.aes = FALSE,
      fill = "grey70",
      alpha = 0.3
    ) +
    geom_line(
      data = pred_df,
      aes(x = q, y = fit),
      inherit.aes = FALSE,
      colour = "black",
      linewidth = 0.9
    ) +
    facet_wrap(
      ~ stage,
      scales = "free_y",
      ncol = 4,
      labeller = as_labeller(stage_label_map)
    ) +
    labs(
      x = "Relative density (N/K)",
      y = ylab,
      color = "Tube"
    ) +
    theme_classic()
}

p_mean <- plot_stage_metric("Mean", "mean_size", "Mean body size")
p_cv   <- plot_stage_metric("CV", "cv_size", "CV of body size")
p_skew <- plot_stage_metric("Skewness", "skew_size", "Skewness of body size")


