bootstrap_nls_ci <- function(model_object, data, predictor, response, B = 500, grid_n = 100) {
  library(minpack.lm)
  library(dplyr)
  
  model_formula <- formula(model_object)
  start_vals <- as.list(coef(model_object))
  
  # Build prediction grid
  
  pred_grid <- data.frame(seq(
    min(data[[predictor]], na.rm = TRUE),
    max(data[[predictor]], na.rm = TRUE),
    length.out = grid_n
  ))
  names(pred_grid) <- predictor
  
  preds <- matrix(NA, nrow = B, ncol = nrow(pred_grid))
  
  for (i in seq_len(B)) {
    sample_data <- data %>%
      dplyr::ungroup() %>%
      dplyr::slice_sample(n = nrow(.), replace = TRUE)
    
    fit <- try(nlsLM(model_formula, data = sample_data, start = start_vals, control = nls.lm.control(maxiter = 500)), silent = TRUE)
    
    if (!inherits(fit, "try-error")) {
      preds[i, ] <- predict(fit, newdata = pred_grid)
    }
  }
  
  # Fitted values from the original model
  pred_grid$fit <- predict(model_object, newdata = pred_grid)
  pred_grid$lwr <- apply(preds, 2, function(x) quantile(x, 0.025, na.rm = TRUE))
  pred_grid$upr <- apply(preds, 2, function(x) quantile(x, 0.975, na.rm = TRUE))
  
  return(pred_grid)
}

ribbon_cal<-function (mdl) {
  best_model<-get(mdl)
  if (mdl == "best_model_mean") {
    dataset <- summary_StaTest_scaled_clean
  } else {
    dataset <- summary_StaTest_clean
  }
  if (inherits(best_model, "lm") && length(coef(best_model)) == 1) {
    ci <- confint(best_model)  # Default is 95% CI
    ci_lower <- ci[1, 1]
    ci_upper <- ci[1, 2]
    intercept <<- coef(best_model)[1]
    # Create a dummy x range for the ribbon
    x_range <- range(dataset$nototal, na.rm = TRUE)
    ribbon_df <- data.frame(
      nototal = x_range,
      lwr = ci_lower,
      upr = ci_upper
    )
  }
  else if (inherits(best_model, "lm") && length(coef(best_model)) > 1) {
    ribbon_df <- data.frame(nototal = seq(min(dataset[["nototal"]], na.rm = TRUE),
                                          max(dataset[["nototal"]], na.rm = TRUE),
                                          length.out = 100))
    fit <- predict(best_model, newdata = ribbon_df, interval = "confidence")
    ribbon_df <- cbind(ribbon_df, fit)
  } else {
    ribbon_df <- bootstrap_nls_ci(
      model_object = best_model,
      data = dataset,
      predictor = "nototal",
      response = ifelse(mdl=="best_model_mean",  "mean_size","CV_size"),
      B = 500,
      grid_n = 100
    )}
  return(ribbon_df)
} 

