                  inherit.aes = FALSE, fill = "black", alpha = 0.2) +
      geom_text(data = label_data_CV, aes(x = x, y = y, label = label),
                inherit.aes = FALSE, hjust = 0, size = 2)+
      xlim(0,800) +
      ylim(0,0.4)+
      theme_minimal() +
      labs(
        title = stg,
        x = ifelse(stg=="deutos"|stg=="protos"|stg=="larvae"|stg=="eggs", 
                   "Population size", ""),
        y = ifelse(stg=="F"|stg=="Qtritos"|stg=="tritos"|stg=="larvae", 
                   "CV of body size", ""),
        color = "Population Stage"
      ) +
      theme(
        legend.position = ifelse(stg=="SM","right", "none")
      )
    
    ## Conditionally add line for mean plot
    if (inherits(best_model_CV, "lm") && length(coef(best_model_CV)) == 1) {
      CV_size_vs_nototal <- CV_size_vs_nototal+
        geom_hline(yintercept = intercept, color = "black", size = 1)
      
    } else {
      CV_size_vs_nototal <- CV_size_vs_nototal +  
        geom_line(data=ribbon_df, aes(x = nototal, y = fit), color = "black", size = 1)
    }
    
    plot_list_mean[[stg]] <- mean_size_vs_nototal
    plot_list_CV[[stg]] <-CV_size_vs_nototal
}

top_row_mean <- plot_list_mean[["F"]] | plot_list_mean[["FM"]]|plot_list_mean[["SM"]]
mid_up_row_mean <-plot_list_mean[["Qtritos"]] | plot_list_mean[["Qprotos"]]|
  plot_list_mean[[ "Qlarvae"]]
mid_bottom_row_mean <-plot_list_mean[["tritos"]]|plot_list_mean[["deutos"]]|
  plot_list_mean[["protos"]] 
bottom_row_mean<-  plot_list_mean[["larvae"]]|plot_list_mean[[ "eggs"]]

top_row_CV <- plot_list_CV[["F"]] | plot_list_CV[["FM"]]|plot_list_CV[["SM"]]
mid_up_row_CV <-plot_list_CV[["Qtritos"]] | plot_list_CV[["Qprotos"]]|
  plot_list_CV[[ "Qlarvae"]]
mid_bottom_row_CV <-plot_list_CV[["tritos"]]|plot_list_CV[["deutos"]]|
  plot_list_CV[["protos"]] 
bottom_row_CV<-  plot_list_CV[["larvae"]]|plot_list_CV[[ "eggs"]]


# Combine plots for adults
final_plot_mean <- top_row_mean /
  mid_up_row_mean /
  mid_bottom_row_mean /
  bottom_row_mean +
  plot_layout(heights = c(1, 1, 1, 1)) +   # 4 heights
  plot_annotation(tag_levels = 'a')
final_plot_mean

final_plot_CV <- top_row_CV /
  mid_up_row_CV /
  mid_bottom_row_CV /
  bottom_row_CV +
  plot_layout(heights = c(1, 1, 1, 1)) +   # 4 heights
  plot_annotation(tag_levels = 'a')
final_plot_CV


#Save
ggsave(paste("Results/mean body size vs population size.tiff", sep = ""), 
       final_plot_mean, width = 8, height = 9, dpi = 600, compression = "lzw")

ggsave(paste("Results/CV of body size  vs population size.tiff", sep = ""), 
